const [name, email, title] = process.argv.slice(1);
const url = new URL(process.env.url);
const password = require('crypto').randomBytes(24).toString('base64url');
let cookie = '';
const call = async (method, path, body) => {
  const response = await fetch(`http://127.0.0.1:2368${url.pathname.replace(/\/$/, '')}/ghost/api/admin${path}`, { method, headers: { 'content-type': 'application/json', origin: url.origin, host: url.host, 'x-forwarded-proto': 'https', ...(cookie ? { cookie } : {}) }, body: body ? JSON.stringify(body) : undefined, redirect: 'manual' });
  const set = response.headers.get('set-cookie'); if (set) cookie = set.split(';')[0];
  const text = await response.text();
  if (!response.ok) throw new Error(`${method} ${path} answered ${response.status}: ${text.slice(0, 300)}`);
  return text.startsWith('{') ? JSON.parse(text) : null;
};
(async () => {
  if ((await call('GET', '/authentication/setup/')).setup[0].status) throw new Error('This site already has an owner.');
  await call('POST', '/authentication/setup/', { setup: [{ name, email, password, blogTitle: title }] });
  await call('POST', '/session/', { username: email, password });
  const made = await call('POST', '/integrations/?include=api_keys', { integrations: [{ name: 'Workshop' }] });
  const admin = made.integrations[0].api_keys.find(key => key.type === 'admin');
  process.stdout.write(JSON.stringify({ site_url: url.origin + url.pathname.replace(/\/$/, ''), admin_api_key: admin.secret.includes(":") ? admin.secret : `${admin.id}:${admin.secret}` }));
})().catch(error => { process.stderr.write(error.message); process.exit(1); });

